import {VERSION,TYPES,BASES,GROUPS,DEFAULT_GOAL,clone,uid,normalize,escapeHtml as h,numberOrNull as num,formatNumber as f,today,dateLabel,emptyState,findExercise,resolveExercise,exerciseForEntry,completedSets,completedExercises,guessExercise,blankSet,queueRecord,mergeSync,validateSet,sessionSummary,previousEntry,setDescription,exerciseSeries,measurementSeries,weeklySeries,goalProgress} from './core.js';

const $=(s,root=document)=>root.querySelector(s), $$=(s,root=document)=>[...root.querySelectorAll(s)];
const STORE='setbook-notebook-v1', CONFIG='setbook-connection-v1';
const paths={notebook:'<rect x="5" y="3" width="15" height="18" rx="2"/><path d="M9 3v18M12 8h5M12 12h5M12 16h3M3 7h3M3 12h3M3 17h3"/>',history:'<circle cx="12" cy="12" r="9"/><path d="M12 7v5l3 2M3 4v5h5"/>',chart:'<path d="M4 3v17h17M7 15l5-5 4 2 5-7"/>',body:'<path d="M9 4h6l2 5-1 4 2 7h-4l-2-5-2 5H6l2-7-1-4z"/>',settings:'<path d="m9 3 6 0 1 3 3 1 2 5-2 5-3 1-1 3H9l-1-3-3-1-2-5 2-5 3-1z"/><circle cx="12" cy="12" r="3"/>',plus:'<path d="M12 5v14M5 12h14"/>',check:'<path d="m5 12 4 4L19 6"/>',close:'<path d="m6 6 12 12M6 18 18 6"/>',more:'<circle cx="5" cy="12" r="1"/><circle cx="12" cy="12" r="1"/><circle cx="19" cy="12" r="1"/>',arrow:'<path d="M5 12h14m-5-5 5 5-5 5"/>',download:'<path d="M12 3v12m-4-4 4 4 4-4M5 16v4h14v-4"/>',refresh:'<path d="M20 8a8 8 0 0 0-14-2L3 9m0-5v5h5M4 16a8 8 0 0 0 14 2l3-3m0 5v-5h-5"/>',edit:'<path d="m4 16 12-12 4 4L8 20H4zM13 7l4 4"/>'};
const icon=(name)=>`<svg class="icon" viewBox="0 0 24 24" aria-hidden="true">${paths[name]||paths.notebook}</svg>`;
let state,config={endpoint:'',key:'',remember:false},storageOK=true,loadError=null;
try{const raw=localStorage.getItem(STORE);state=raw?JSON.parse(raw):emptyState();if(state.schemaVersion!==1)throw Error('Unsupported notebook version.');}catch(e){state=emptyState();storageOK=false;loadError='Your saved notebook could not be opened. Existing browser data has been preserved. Export or recover it before making changes.';}
try{const saved=JSON.parse(localStorage.getItem(CONFIG)||'{}');config={...config,...saved,key:saved.remember?saved.key||'':sessionStorage.getItem('setbook-access-key')||''};}catch(e){}
let syncing=false,syncError='',syncTimer=null,toastTimer=null,activeTab='workout',exerciseMetric='load',bodyMetric='weightKg',selectedExercise='',includeEstimated=true,historySearch='',historyYear='all',pendingImport=null,singleTabBlocked=false;
const main=$('#main'),modal=$('#modal');
$('#settings-button').innerHTML=icon('settings');$('#close-modal').innerHTML=icon('close');
$$('[data-icon]').forEach(el=>el.innerHTML=icon(el.dataset.icon));

function persist() {
  if(!storageOK){showFatal(loadError||'Local saving is unavailable. Export your notebook before leaving this page.');return false;}
  try{localStorage.setItem(STORE,JSON.stringify(state));return true;}catch(e){storageOK=false;showFatal('This device could not save your latest changes. Keep this page open and export a backup from Settings.');return false;}
}
function showFatal(message){$('#fatal-error').hidden=false;$('#fatal-error').textContent=message;}
function toast(message){const el=$('#toast');el.textContent=!storageOK&&/saved on this device/i.test(message)?'Local saving failed. Keep this page open and export a backup from Settings.':message;el.classList.add('visible');clearTimeout(toastTimer);toastTimer=setTimeout(()=>el.classList.remove('visible'),4200);}
function showModal(title,html){$('#modal-title').textContent=title;$('#modal-body').innerHTML=html;if(!modal.open)modal.showModal();}
function closeModal(){modal.close();pendingImport=null;}
function saveConfig(){const saved={endpoint:config.endpoint,remember:config.remember};if(config.remember)saved.key=config.key;localStorage.setItem(CONFIG,JSON.stringify(saved));if(!config.remember)sessionStorage.setItem('setbook-access-key',config.key);else sessionStorage.removeItem('setbook-access-key');}
const configured=()=>Boolean(config.endpoint&&config.key);
function updateStatus(){
 const el=$('#sync-button'),label=$('#sync-label');
 let status='local',text='On this device';
 if(!storageOK){status='error';text='Local save unavailable';}else if(syncing){status='syncing';text='Syncing…';}else if(state.conflicts.length){status='error';text='Review changes';}else if(syncError){status='error';text='Retry sync';}else if(configured()&&!navigator.onLine){text=state.pending.length?'Saved · offline':'Offline';}else if(configured()&&state.pending.length){text=`${state.pending.length} change${state.pending.length===1?'':'s'} waiting`;}else if(configured()&&state.lastSync){status='synced';text='Synced';}
 el.dataset.status=status;label.textContent=text;el.title=syncError||(state.lastSync?'Last sync: '+new Date(state.lastSync).toLocaleString():'Connect Google Sheets in Settings');
}
function changed(entity,record,{renderNow=false}={}){
 if(singleTabBlocked)return;
 record.clientUpdatedAt=new Date().toISOString();queueRecord(state,entity,record);persist();updateStatus();scheduleSync();if(renderNow)render();
}
function scheduleSync(){clearTimeout(syncTimer);if(configured()&&navigator.onLine)syncTimer=setTimeout(()=>sync(false),1400);}
async function request(body){
 const controller=new AbortController(),timer=setTimeout(()=>controller.abort(),45000);
 try{
  const response=await fetch(config.endpoint,{method:'POST',headers:{'Content-Type':'text/plain;charset=UTF-8'},body:JSON.stringify({...body,accessKey:config.key}),credentials:'omit',redirect:'follow',cache:'no-store',signal:controller.signal});
  if(!response.ok)throw Error('Google returned HTTP '+response.status+'. Check the deployment and access settings.');
  const text=await response.text();let result;
  try{result=JSON.parse(text);}catch(e){throw Error('Google did not return the notebook response. Deploy as “Me”, allow “Anyone”, and use the /exec URL.');}
  if(!result.ok)throw Error(result.error||'The server could not save this request.');return result;
 }catch(e){if(e.name==='AbortError')throw Error('The request timed out. Your changes remain on this device; retrying will not duplicate records.');if(e instanceof TypeError)throw Error('Could not confirm a connection. Check your internet, /exec URL, and “Anyone” deployment access. Your changes remain on this device.');throw e;}finally{clearTimeout(timer);}
}
async function sync(force=false){
 if(syncing||singleTabBlocked)return false;if(!configured()){if(force)openSettings();return false;}if(!navigator.onLine){if(force)toast('Offline. Changes are saved on this device.');updateStatus();return false;}
 const sent=clone(state.pending.filter(o=>!state.conflicts.some(c=>c.key===o.key)).slice(0,40));
 if(!sent.length&&!force)return !state.conflicts.length;
 syncing=true;syncError='';updateStatus();
 try{const response=await request({action:'sync',operations:sent});mergeSync(state,response,sent);persist();if(response.warning)toast(response.warning);if(state.conflicts.length)toast('Another device changed the same record. Review both versions before syncing it.');updateStatus();if(!document.activeElement?.matches('input,textarea,select')&&!modal.open)render();return !state.conflicts.length;}
 catch(e){syncError=e.message;if(force)toast(syncError);return false;}
 finally{syncing=false;updateStatus();if(state.pending.some(o=>!state.conflicts.some(c=>c.key===o.key))&&!syncError)scheduleSync();}
}
function currentSession(){return state.sessions.find(s=>s.id===state.activeSessionId&&!s.deleted);}
function findEntry(id){return currentSession()?.entries.find(e=>e.id===id);}
function entryView(entry){return {...(exerciseForEntry(state,entry)||{}),...entry,name:exerciseForEntry(state,entry)?.name||entry.name};}
function setFromElement(el){const row=el.closest('[data-set]'),entry=findEntry(row?.dataset.entry);return {row,entry,set:entry?.sets.find(s=>s.id===row.dataset.set)};}
function saveCurrent(renderNow=false){const s=currentSession();if(s)changed('session',s,{renderNow});}
function pageHead(eyebrow,title,subtitle,right=''){return `<div class="page-head"><div><p class="eyebrow">${eyebrow}</p><h1 class="page-title">${title}</h1><p class="subtle">${subtitle}</p></div>${right}</div>`;}
function notices(){let html='';if(!configured())html+=`<div class="connect-strip"><div><strong>Your notebook, ready to connect.</strong><p>Entries stay on this device until Google Sheets is connected.</p></div><button class="secondary" data-action="settings">Connect</button></div>`;if(state.conflicts.length)html+=`<div class="notice error"><div><strong>${state.conflicts.length} change${state.conflicts.length===1?'':'s'} to review</strong><p>A copy on another device was edited too.</p></div><button class="secondary" data-action="conflicts">Review</button></div>`;if(syncError)html+=`<div class="notice error"><div><strong>Sync not confirmed</strong><p>${h(syncError)}</p></div><button class="secondary" data-action="sync">Retry</button></div>`;return html;}
function render(){
 activeTab=['workout','history','progress','body'].includes(location.hash.slice(1))?location.hash.slice(1):'workout';
 $$('.bottom-nav a').forEach(a=>{if(a.dataset.tab===activeTab)a.setAttribute('aria-current','page');else a.removeAttribute('aria-current');});
 if(activeTab==='workout')renderWorkout();else if(activeTab==='history')renderHistory();else if(activeTab==='progress')renderProgress();else renderBody();updateStatus();
 if(singleTabBlocked||loadError)main.inert=true;
}
function renderWorkout(){
 const weekly=weeklySeries(state,1)[0].value,goal={...DEFAULT_GOAL,...state.settings.find(x=>x.id==='preferences')};
 const session=currentSession();let html=pageHead('Your training notebook','Today’s workout',h(dateLabel(today(),{weekday:'long',year:'numeric'})),`<div class="week-marker">${weekly}<span class="subtle"> / ${goal.weeklyTarget}</span><small>sessions this week</small></div>`)+notices();
 if(!session){
  const resumable=state.sessions.filter(s=>!s.deleted&&s.status==='active').sort((a,b)=>(b.date||'').localeCompare(a.date||''));
  html+=`<div class="empty-start"><div class="empty-icon">${icon('notebook')}</div><h2>A fresh page.</h2><p>Start your session, choose an exercise, and record each set as you go.</p><button class="primary" data-action="start">${icon('plus')}Start workout</button>${resumable.map(s=>`<button class="text-button" data-action="edit-session" data-id="${h(s.id)}">Resume ${h(s.date?dateLabel(s.date):s.label)} · ${sessionSummary(s)}</button>`).join('')}</div>`;
  const last=state.sessions.filter(s=>!s.deleted&&s.status==='completed').sort((a,b)=>(b.date||'').localeCompare(a.date||''))[0];
  if(last)html+=`<div class="side-card" style="margin-top:22px"><div class="row-between"><div><p class="eyebrow">Previous session</p><h2 class="section-title" style="margin:0">${h(last.date?dateLabel(last.date):last.label)}</h2><p>${sessionSummary(last)}</p></div><button class="secondary" data-action="repeat-session" data-id="${h(last.id)}">Repeat exercises</button></div></div>`;
 }else{
  const groups=new Set(session.entries.filter(e=>e.sets.some(s=>s.completed)).map(e=>e.group));
  const count=completedExercises(session),setCount=completedSets(session).length;
  html+=`<div class="session-toolbar"><div class="session-meta"><input aria-label="Workout date" type="date" id="workout-date" value="${h(session.date||'')}"><span class="subtle">${session.status==='completed'?'Editing history':'In progress'}</span></div><div class="button-row"><button class="icon-button" data-action="session-menu" aria-label="Workout options">${icon('more')}</button><button class="secondary" data-action="finish">${session.status==='completed'?'Done editing':'Finish workout'}</button></div></div><div class="workout-layout"><section class="workout-main" aria-label="Exercise log">${session.entries.map((e,i)=>renderExercise(e,i)).join('')}${!session.entries.length?'<p class="empty-session-tip">Choose your first exercise to begin.</p>':''}<button class="add-exercise" data-action="add-exercise">${icon('plus')} Add exercise</button></section><aside class="sidebar"><div class="side-card"><h3>This session</h3><div class="chart-meta"><span class="chart-value">${count}<span class="subtle"> / 6</span></span><span class="chart-unit">exercises</span></div><p>${setCount} completed sets${session.startedAt?' · started '+h(new Date(session.startedAt).toLocaleTimeString([],{hour:'2-digit',minute:'2-digit'})):''}</p><div class="coverage">${['Push','Pull','Legs','Core','Carry','Cardio'].map(g=>`<span class="group-tag ${groups.has(g)?'hit':''}">${g}</span>`).join('')}</div><p>Groups reflect your entries. Compound exercises can involve several groups.</p></div><div class="side-card notes-card"><h3>Workout notes</h3><label class="visually-hidden" for="workout-notes">General workout notes</label><textarea id="workout-notes" rows="5" maxlength="4000" placeholder="How did the session feel?" style="width:100%;background:var(--panel);border:1px solid var(--line);border-radius:7px;padding:12px;resize:vertical;font-size:13px">${h(session.notes||'')}</textarea></div><button class="text-button" data-action="close-session">Return to today</button></aside></div>`;
 }
 main.innerHTML=html;
}
function numericInput(field,value,label,{step='any',placeholder='—',max=null}={}){return `<input type="number" data-field="${field}" value="${value??''}" inputmode="${step==='1'?'numeric':'decimal'}" min="0" ${max!=null?`max="${max}"`:''} step="${step}" placeholder="${placeholder}" aria-label="${h(label)}" autocomplete="off">`;}
function renderExercise(entry,i){
 const e=entryView(entry),previous=previousEntry(state,entry.exerciseId,currentSession().id),sets=previous?.entry.sets.filter(s=>s.completed)||[];
 const left=e.type==='cardio'?'Time · min':e.loadBasis==='perArm'?'Kg / arm':e.loadBasis==='dumbbell'?'Kg / DB':'Load · kg';
 const right=e.type==='timed'?'Hold · sec':e.type==='cardio'?'Km/h':e.type==='carry'?'Distance · m':'Reps';
 return `<article class="exercise-card" data-exercise-card="${h(entry.id)}"><div class="exercise-top"><span class="exercise-number">${String(i+1).padStart(2,'0')}</span><div class="exercise-title-wrap"><h2 class="exercise-title">${h(e.name)}</h2><div class="exercise-tags"><span class="tag">${h(e.group)}</span><span class="basis">${h(BASES[e.loadBasis])}</span></div></div><button class="icon-button" data-action="entry-options" data-id="${h(entry.id)}" aria-label="Options for ${h(e.name)}">${icon('more')}</button></div>${previous?`<div class="previous"><span>LAST · ${h(previous.session.date?dateLabel(previous.session.date):previous.session.label)}</span><br>${h(sets.slice(0,4).map(s=>setDescription(s,previous.entry)).join(' / '))}${sets.length>4?' …':''}</div>`:''}<div class="set-table"><div class="set-labels"><span>Set</span><span>${left}</span><span>${right}</span><span title="Reached failure">Fail</span><span>Done</span></div>${entry.sets.map((s,j)=>renderSet(entry,s,j)).join('')}</div><div class="exercise-footer"><button class="text-button" data-action="add-set" data-id="${h(entry.id)}">+ Add set</button>${previous?`<button class="text-button" data-action="copy-previous" data-id="${h(entry.id)}">Copy last session</button>`:''}<button class="text-button" data-action="entry-note" data-id="${h(entry.id)}">${entry.notes?'Edit note':'Add note'}</button></div>${entry.notes?`<p class="exercise-note">${h(entry.notes)}</p>`:''}</article>`;
}
function renderSet(e,s,i){
 const primary=e.type==='cardio'?numericInput('minutes',s.seconds==null?null:Math.round(s.seconds/60*100)/100,`${e.name}, set ${i+1}, minutes`):numericInput('loadKg',s.loadKg,`${e.name}, set ${i+1}, ${BASES[e.loadBasis]}, kilograms`);
 const field=e.type==='strength'?'reps':e.type==='timed'?'seconds':e.type==='carry'?'distanceM':'speedKmh';
 const captions={reps:'repetitions',seconds:'hold seconds',distanceM:'distance in metres',speedKmh:'speed in kilometres per hour'};
 let extras='';
 if(e.type==='carry')extras+=`<label>Sec ${numericInput('seconds',s.seconds,'Carry duration in seconds')}</label>${s.loadKg!=null?`<span>${f(s.loadKg*2)} kg total carried</span>`:''}`;
 if(e.type==='cardio')extras+=`<label>Metres ${numericInput('distanceM',s.distanceM,'Distance in metres')}</label><label>Incline % ${numericInput('incline',s.incline,'Treadmill incline percent',{max:100})}</label>`;
 return `<div class="set-row ${s.completed?'done':''}" data-entry="${h(e.id)}" data-set="${h(s.id)}"><button class="set-index" data-action="set-details" aria-label="Set ${i+1} details">${i+1}${s.kind==='drop'?'<small>D</small>':s.kind==='warmup'?'<small>W</small>':''}</button>${primary}${numericInput(field,s[field],`${e.name}, set ${i+1}, ${captions[field]}`,{step:field==='reps'?'1':'any'})}<label class="set-check failure-check"><input type="checkbox" data-field="failure" ${s.failure?'checked':''} aria-label="Set ${i+1} reached failure"></label><label class="set-check"><input type="checkbox" data-field="completed" ${s.completed?'checked':''} aria-label="Complete set ${i+1} of ${h(e.name)}"></label><div class="set-extra">${extras}${s.estimated?'<span>Imported estimate</span>':''}${s.kind!=='work'?`<span>${s.kind==='drop'?'Drop set':'Warm-up'}</span>`:''}<button class="text-button" data-action="set-details" aria-label="More details for set ${i+1}">Details</button></div></div>`;
}
function startSession(source){
 const entries=source?(source.entries||[]).map(e=>({...clone(e),id:uid(),notes:'',historical:false,sets:e.sets.filter(s=>s.completed).map(s=>({...clone(s),id:uid(),completed:false,failure:false,estimated:false,imported:false}))})):[];
 const s={id:uid(),date:today(),label:'',status:'active',notes:'',startedAt:new Date().toISOString(),finishedAt:null,entries,_rev:0};state.sessions.push(s);state.activeSessionId=s.id;changed('session',s);location.hash='#workout';render();
}
function openExercisePicker(){
 showModal('Add an exercise',`<p class="modal-intro">Choose from your notebook, or type a new exercise. New names join your list after the first completed set.</p><div class="field"><label for="exercise-search">Exercise name</label><input id="exercise-search" type="search" maxlength="120" placeholder="Search or type a new name" autocomplete="off"></div><div id="exercise-options"></div>`);renderExerciseOptions('');setTimeout(()=>$('#exercise-search')?.focus(),50);
}
function renderExerciseOptions(query){
 const list=state.exercises.filter(e=>!e.archived&&!e.deleted&&!e.redirectId&&(normalize(e.name).includes(normalize(query))||(e.aliases||[]).some(a=>normalize(a).includes(normalize(query)))));
 const recentIds=state.sessions.filter(s=>!s.deleted).sort((a,b)=>(b.date||'').localeCompare(a.date||'')).flatMap(s=>s.entries.map(e=>resolveExercise(state.exercises,e.exerciseId)?.id||e.exerciseId));
 list.sort((a,b)=>(recentIds.indexOf(a.id)<0?999:recentIds.indexOf(a.id))-(recentIds.indexOf(b.id)<0?999:recentIds.indexOf(b.id))||a.name.localeCompare(b.name));
 const exact=findExercise(state.exercises,query),newName=query.trim().replace(/\s+/g,' ');
 $('#exercise-options').innerHTML=`<div class="search-list">${list.map(e=>`<button class="exercise-option" data-action="choose-exercise" data-id="${h(e.id)}"><span><strong>${h(e.name)}</strong><small>${h(e.group)} · ${h(BASES[e.loadBasis])}</small></span>${icon('plus')}</button>`).join('')}${!list.length?'<p class="subtle">No matching exercises yet.</p>':''}</div>${newName&&!exact?`<button class="primary wide" data-action="new-exercise">${icon('plus')} Add “${h(newName)}”</button>`:''}${exact?.archived?`<button class="secondary wide" data-action="choose-exercise" data-id="${h(exact.id)}">Use archived exercise: ${h(exact.name)}</button>`:''}`;
}
function exerciseFields(e){return `<div class="two-col"><div class="field"><label for="ex-type">Log format</label><select id="ex-type">${Object.entries(TYPES).map(([k,v])=>`<option value="${k}" ${e.type===k?'selected':''}>${v}</option>`).join('')}</select></div><div class="field"><label for="ex-group">Main group</label><select id="ex-group">${GROUPS.map(g=>`<option ${g===e.group?'selected':''}>${g}</option>`).join('')}</select></div></div><div class="field"><label for="ex-basis">Weight convention</label><select id="ex-basis">${Object.entries(BASES).map(([k,v])=>`<option value="${k}" ${e.loadBasis===k?'selected':''}>${v}</option>`).join('')}</select></div>`;}
function newExercise(){const name=$('#exercise-search').value.trim().replace(/\s+/g,' ');if(!name)return;const e=guessExercise(name);showModal('New exercise',`<form id="new-exercise-form"><div class="field"><label for="ex-name">Exercise name</label><input id="ex-name" value="${h(name)}" required maxlength="120"></div>${exerciseFields(e)}<p class="fine-print">You can change these details later. The name is added to your exercise list when you complete a set.</p><p class="form-error" id="exercise-error"></p><button class="primary wide" type="submit">Add to workout</button></form>`);}
function addExercise(e){const s=currentSession();if(!s)return;const entry={id:uid(),exerciseId:e.id,name:e.name,type:e.type,loadBasis:e.loadBasis,group:e.group,notes:'',sets:[blankSet()]};s.entries.push(entry);saveCurrent();closeModal();render();setTimeout(()=>$(`[data-exercise-card="${entry.id}"]`)?.scrollIntoView({behavior:'smooth',block:'center'}),30);}
function registerLocal(e){if(!state.exercises.some(x=>x.id===e.exerciseId)){const same=findExercise(state.exercises,e.name);if(same)e.exerciseId=same.id;else state.exercises.push({id:e.exerciseId,name:e.name,type:e.type,loadBasis:e.loadBasis,group:e.group,aliases:[],archived:false,_rev:0});}}

function renderHistory(){
 let sessions=state.sessions.filter(s=>!s.deleted).sort((a,b)=>(b.date||'').localeCompare(a.date||'')||(a.label||'').localeCompare(b.label||''));
 const years=[...new Set(sessions.map(s=>s.date?.slice(0,4)).filter(Boolean))].sort().reverse();
 main.innerHTML=pageHead('Your previous pages','Workout history','Revisit a session, make a correction, or repeat its exercises.')+notices()+`<div class="history-filter"><input id="history-search" class="standalone" type="search" placeholder="Search exercise or notes" aria-label="Search workout history" value="${h(historySearch)}"><select id="history-year" class="standalone" aria-label="Filter history by year" style="width:110px"><option value="all">All dates</option>${years.map(y=>`<option ${historyYear===y?'selected':''}>${y}</option>`).join('')}<option value="undated" ${historyYear==='undated'?'selected':''}>Undated</option></select></div><div id="history-list"></div>`;
 renderHistoryList();
}
function renderHistoryList(){
 const q=normalize(historySearch);const list=state.sessions.filter(s=>!s.deleted&&(historyYear==='all'||(historyYear==='undated'?!s.date:s.date?.startsWith(historyYear)))&&(!q||normalize([s.notes,s.label,...s.entries.map(e=>entryView(e).name+' '+(e.notes||''))].join(' ')).includes(q))).sort((a,b)=>(b.date||'').localeCompare(a.date||'')||(a.label||'').localeCompare(b.label||''));
 $('#history-list').innerHTML=list.length?list.map(s=>`<details class="history-item"><summary><div class="history-header"><div><h2 class="history-date">${h(s.date?dateLabel(s.date,{year:'numeric'}):s.label||'Undated workout')}</h2><span class="subtle">${sessionSummary(s)}${s.status==='active'?' · In progress':''}</span></div>${icon('arrow')}</div></summary><div class="history-content">${s.entries.map(e=>`<div class="history-exercise"><strong>${h(entryView(e).name)}</strong><p>${h(e.sets.filter(x=>x.completed).map(x=>setDescription(x,e)+(x.failure?' · failure':'')+(x.estimated?' *':'')).join(' / ')||'Set details not recorded')}</p>${e.notes?`<p>${h(e.notes)}</p>`:''}</div>`).join('')}${s.notes?`<p class="history-note">${h(s.notes)}</p>`:''}${s.imported?'<p class="fine-print">* Estimated during import. Original values are preserved in Google Sheets.</p>':''}<div class="button-row"><button class="secondary" data-action="edit-session" data-id="${h(s.id)}">Edit workout</button><button class="secondary" data-action="repeat-session" data-id="${h(s.id)}">Repeat exercises</button><button class="text-button danger-text" data-action="delete-session" data-id="${h(s.id)}">Delete</button></div></div></details>`).join(''):'<div class="empty-message">No workouts match this page yet.</div>';
}
function chart(points,{unit='',bars=false,label='Progress',target=null}={}){
 if(!points.length)return '<div class="empty-message">Complete a workout or add a measurement to start this graph.</div>';
 const w=600,height=225,left=45,right=15,top=18,bottom=40,plotW=w-left-right,plotH=height-top-bottom;
 const values=points.map(p=>p.value),minValue=Math.min(...values),maxValue=Math.max(...values,typeof target==='number'?target:0);
 let low=bars?0:Math.max(0,minValue-(maxValue-minValue||Math.max(1,minValue*.05))*.25),high=bars?Math.max(3,maxValue+1):maxValue+(maxValue-low||1)*.15;
 if(high===low)high=low+1;
 const dates=points.map(p=>Date.parse(p.date+'T12:00:00Z')),minX=Math.min(...dates),maxX=Math.max(...dates),x=(p,i)=>bars?left+(i+.5)*plotW/points.length:dates.length===1||maxX===minX?left+plotW/2:left+(dates[i]-minX)/(maxX-minX)*plotW,y=v=>top+plotH-(v-low)/(high-low)*plotH;
 const ticks=Array.from({length:4},(_,i)=>low+(high-low)*i/3);
 const grid=ticks.map(v=>`<path class="grid" d="M${left},${y(v)}H${w-right}"/><text x="${left-9}" y="${y(v)+3}" text-anchor="end">${f(v,bars?0:1)}</text>`).join('');
 const stride=Math.max(1,Math.ceil(points.length/5));const labels=points.map((p,i)=>(i%stride===0||i===points.length-1)?`<text x="${x(p,i)}" y="${height-13}" text-anchor="middle">${h(dateLabel(p.date))}</text>`:'').join('');
 let plot='';
 if(bars)plot=points.map((p,i)=>`<rect class="bar" x="${x(p,i)-Math.min(24,plotW/points.length*.3)}" y="${y(p.value)}" width="${Math.min(48,plotW/points.length*.6)}" height="${Math.max(0,y(0)-y(p.value))}" rx="3"><title>${h(p.label)}: ${p.value} ${unit}</title></rect>`).join('');
 else {const coords=points.map((p,i)=>`${x(p,i)},${y(p.value)}`);plot=`<path class="area" d="M${x(points[0],0)},${top+plotH}L${coords.join(' L')}L${x(points.at(-1),points.length-1)},${top+plotH}Z"/><polyline class="plot-line" points="${coords.join(' ')}"/>`+points.map((p,i)=>`<circle class="point ${p.estimated?'estimate':''}" cx="${x(p,i)}" cy="${y(p.value)}" r="4"><title>${h(p.label)}: ${f(p.value)} ${unit}${p.estimated?' (includes import estimate)':''}</title></circle>`).join('');}
 return `<svg class="chart" viewBox="0 0 ${w} ${height}" role="img" aria-label="${h(label)}"><title>${h(label)}</title><desc>${h(points.map(p=>`${dateLabel(p.date)}: ${f(p.value)} ${unit}`).join('; '))}</desc>${grid}${plot}${labels}</svg><details class="chart-data"><summary>View data</summary><table><thead><tr><th scope="col">Date</th><th scope="col">${h(unit||'Value')}</th><th scope="col">Note</th></tr></thead><tbody>${points.map(p=>`<tr><td>${h(dateLabel(p.date,{year:'numeric'}))}</td><td>${f(p.value)}</td><td>${p.estimated?'Imported estimate':''}</td></tr>`).join('')}</tbody></table></details>`;
}
function renderProgress(){
 const completed=state.sessions.filter(s=>!s.deleted&&s.status==='completed'&&completedSets(s).length),count=completed.length,setCount=completed.reduce((n,s)=>n+completedSets(s).length,0),weekly=weeklySeries(state);
 const usedIds=new Set(completed.flatMap(s=>s.entries.filter(e=>e.sets.some(x=>x.completed)).map(e=>resolveExercise(state.exercises,e.exerciseId)?.id||e.exerciseId)));
 const exercises=state.exercises.filter(e=>usedIds.has(e.id)&&!e.redirectId&&!e.deleted).sort((a,b)=>a.name.localeCompare(b.name));
 if(!selectedExercise||!exercises.some(e=>e.id===selectedExercise))selectedExercise=exercises.find(e=>/bench press/i.test(e.name))?.id||exercises[0]?.id||'';
 const exercise=exercises.find(e=>e.id===selectedExercise),series=exerciseSeries(state,selectedExercise,exerciseMetric,includeEstimated),unit={load:'kg',reps:'reps',sets:'sets',duration:'sec',distance:'m'}[exerciseMetric];
 main.innerHTML=pageHead('Small changes, over time','Training progress','Compare the same exercise, equipment, and weight convention.')+notices()+`<div class="stats-grid"><div class="stat-box"><small>Completed workouts</small><strong>${count}</strong><span>including undated sessions</span></div><div class="stat-box"><small>Completed sets</small><strong>${setCount}</strong><span>all recorded training</span></div><div class="stat-box"><small>This week</small><strong>${weekly.at(-1).value}</strong><span>dated workouts</span></div></div><div class="progress-grid"><section class="chart-card"><h2 class="section-title">Exercise notebook</h2><div class="chart-controls"><select id="progress-exercise" aria-label="Choose exercise for graph">${exercises.map(e=>`<option value="${h(e.id)}" ${e.id===selectedExercise?'selected':''}>${h(e.name)}</option>`).join('')||'<option>No exercises yet</option>'}</select><select id="progress-metric" aria-label="Choose exercise metric">${[['load','Top logged load'],['reps','Most reps in one set'],['sets','Completed sets'],['duration','Longest hold / activity'],['distance','Longest distance']].map(([k,v])=>`<option value="${k}" ${k===exerciseMetric?'selected':''}>${v}</option>`).join('')}</select></div><label class="inline-check"><input id="include-estimated" type="checkbox" ${includeEstimated?'checked':''}>Include estimated import values</label><div class="chart-meta"><span class="chart-value">${series.length?f(series.at(-1).value):'—'}</span><span class="chart-unit">${unit} · latest session</span></div><p class="fine-print">${exercise?h(BASES[exercise.loadBasis]):'Your completed sets will appear here.'}${exerciseMetric==='load'&&exercise?.loadBasis==='plates'?' · Bar weight excluded.':''}</p>${chart(series,{unit,label:'Exercise '+exerciseMetric+' over time'})}<p class="fine-print">Only completed sets in finished, dated workouts appear. Reps and load are separate measures. Undated sessions remain in History.</p></section><section class="chart-card"><h2 class="section-title">Showing up</h2><p class="subtle">Completed sessions, week beginning Monday</p>${chart(weekly,{unit:'workouts',bars:true,label:'Weekly completed workouts'})}<p class="fine-print">Your target is two sessions each week. This graph counts workouts with at least one completed set.</p></section></div>`;
}
function renderBody(){
 const metrics=[['weightKg','Body weight','kg'],['bodyFatPct','Body fat','%'],['skeletalMuscleKg','Skeletal muscle','kg']],series=measurementSeries(state,bodyMetric),m=metrics.find(m=>m[0]===bodyMetric),g=goalProgress(state),percentage=g.change==null?0:Math.max(0,Math.min(100,g.change/g.goal.gainKg*100));
 const records=state.measurements.filter(m=>!m.deleted).sort((a,b)=>b.date.localeCompare(a.date));
 main.innerHTML=pageHead('Body composition','Beyond the scale','Record body weight, body fat, and InBody skeletal muscle mass.',`<button class="primary" data-action="measurement">${icon('plus')} Add reading</button>`)+notices()+`<div class="goal-box"><div class="row-between"><div><p class="eyebrow">Skeletal muscle goal</p><h2>+${f(g.goal.gainKg)} kg by ${h(dateLabel(g.goal.deadline,{year:'numeric'}))}</h2></div><button class="icon-button" data-action="goal" aria-label="Edit muscle goal">${icon('edit')}</button></div><div class="goal-track"><div class="goal-fill" style="--progress:${percentage}%"></div></div><div class="goal-values"><span>${g.change==null?'Add a skeletal muscle reading to begin.':`${g.change>=0?'+':''}${f(g.change)} kg measured change`}</span><span>${g.baseline!=null?`${f(g.baseline)} kg baseline${g.baselineDate?' · '+dateLabel(g.baselineDate):''}`:'Baseline not set'}</span></div><p class="fine-print">This tracks your chosen goal. InBody measurements are estimates; compare scans under similar conditions. Scale weight alone is not counted as muscle gain.</p></div><section class="chart-card"><div class="segmented" aria-label="Body measurement graph">${metrics.map(([k,label])=>`<button data-action="body-metric" data-value="${k}" aria-pressed="${k===bodyMetric}">${label}</button>`).join('')}</div><div class="chart-meta"><span class="chart-value">${series.length?f(series.at(-1).value):'—'}</span><span class="chart-unit">${m[2]}${series.length?' · '+dateLabel(series.at(-1).date):' · no readings yet'}</span></div>${chart(series,{unit:m[2],label:m[1]+' over time'})}</section><div class="section-separator"><h2 class="section-title">Your readings</h2>${records.map(m=>`<div class="measurement-row"><div class="row-between"><strong style="font-weight:500;font-size:13px">${h(dateLabel(m.date,{year:'numeric'}))}</strong><button class="icon-button" data-action="measurement" data-id="${h(m.id)}" aria-label="Edit body reading for ${h(m.date)}">${icon('edit')}</button></div><div class="measurement-numbers">${metrics.filter(([k])=>m[k]!=null).map(([k,label,unit])=>`<span>${label} <strong>${f(m[k])} ${unit}</strong></span>`).join('')}</div>${m.notes?`<p class="history-note">${h(m.notes)}</p>`:''}</div>`).join('')||'<div class="empty-message">Add your first reading whenever you have it. You can enter any of the three measurements.</div>'}</div>`;
}
function openMeasurement(id){const m=state.measurements.find(x=>x.id===id)||{id:uid(),date:today(),weightKg:null,bodyFatPct:null,skeletalMuscleKg:null,notes:'',_rev:0};showModal(id?'Edit reading':'Body reading',`<form id="measurement-form" data-id="${h(m.id)}"><div class="field"><label for="m-date">Reading date</label><input type="date" id="m-date" value="${h(m.date)}" required></div><div class="field"><label for="m-weight">Body weight · kg</label><input id="m-weight" type="number" min="1" max="700" step="0.1" inputmode="decimal" value="${m.weightKg??''}"></div><div class="two-col"><div class="field"><label for="m-fat">Body fat · %</label><input id="m-fat" type="number" min="0" max="100" step="0.1" inputmode="decimal" value="${m.bodyFatPct??''}"></div><div class="field"><label for="m-muscle">Skeletal muscle · kg</label><input id="m-muscle" type="number" min="0" max="400" step="0.1" inputmode="decimal" value="${m.skeletalMuscleKg??''}"></div></div><div class="field"><label for="m-notes">Notes</label><textarea id="m-notes" maxlength="2000" placeholder="InBody scan, time of day, or other context">${h(m.notes)}</textarea></div><p class="fine-print">Leave values you do not have blank. Do not enter total lean mass in the skeletal muscle field.</p><p class="form-error" id="measurement-error"></p><div class="button-row"><button class="primary" type="submit">Save reading</button>${id?`<button type="button" class="text-button danger-text" data-action="delete-measurement" data-id="${h(m.id)}">Delete reading</button>`:''}</div></form>`);}
function openGoal(){const g=goalProgress(state).goal;showModal('Your muscle goal',`<form id="goal-form"><div class="two-col"><div class="field"><label for="goal-gain">Target gain · kg</label><input id="goal-gain" type="number" min="0.1" max="100" step="0.1" value="${g.gainKg}" required inputmode="decimal"></div><div class="field"><label for="goal-deadline">Target date</label><input id="goal-deadline" type="date" value="${h(g.deadline)}" required></div></div><div class="field"><label for="goal-baseline">Starting skeletal muscle mass · kg</label><input id="goal-baseline" type="number" min="0" max="400" step="0.1" value="${g.baselineKg??''}" inputmode="decimal"><small>Leave blank to use your earliest skeletal muscle reading.</small></div><div class="field"><label for="goal-weekly">Weekly session target</label><input id="goal-weekly" type="number" min="1" max="14" step="1" value="${g.weeklyTarget}" required></div><p class="fine-print">December 15 is the initial interpretation of your mid-December deadline. This is a personal tracking goal, not a prediction.</p><button class="primary wide" type="submit">Save goal</button></form>`);}
function openSettings(){
 const remembered=config.remember?'checked':'',theme=document.documentElement.dataset.theme;
 showModal('Notebook settings',`<div class="settings-section"><h3>Appearance</h3><div class="theme-options"><button class="secondary" data-action="theme" data-value="dark" aria-pressed="${theme==='dark'}">Charcoal</button><button class="secondary" data-action="theme" data-value="light" aria-pressed="${theme==='light'}">Paper</button></div></div><div class="settings-section"><h3>Google Sheets connection</h3><p class="settings-note">Connect the Apps Script deployment from your new private Sheet. The setup guide is included in your download.</p><form id="connection-form"><div class="field"><label for="api-url">Apps Script web app URL</label><input id="api-url" type="url" value="${h(config.endpoint)}" placeholder="https://script.google.com/macros/s/…/exec" required autocomplete="url" spellcheck="false"></div><div class="field"><label for="api-key">Private access key</label><input id="api-key" type="password" value="${h(config.key)}" required minlength="20" autocomplete="off" spellcheck="false"></div><label class="inline-check"><input id="remember-key" type="checkbox" ${remembered}>Remember the access key on this device</label><p class="form-error" id="connection-error"></p><button class="primary wide" type="submit">${icon('refresh')} Save & connect</button></form><p class="settings-note" id="connection-status">${state.lastSync?'Last confirmed sync: '+h(new Date(state.lastSync).toLocaleString()):'No confirmed sync yet.'}${state.pending.length?'\n'+state.pending.length+' changes are waiting on this device.':''}</p>${config.endpoint?'<button class="text-button" data-action="disconnect">Disconnect this device</button>':''}</div><div class="settings-section"><h3>Your exercise list</h3><p class="settings-note">Only exercises you have used are listed. Rename, archive, or merge duplicates without removing history.</p><button class="secondary wide" data-action="manage-exercises">Manage exercises</button></div><div class="settings-section"><h3>Starting workout history</h3><p class="settings-note">Choose private-import/history-import.json from your download. Import it once after connecting. November 11’s planned session is excluded.</p><input class="file-picker" type="file" id="history-file" accept="application/json,.json" aria-label="Select starting history file"><div id="import-preview"></div></div><div class="settings-section"><h3>Private backup</h3><p class="settings-note">Download your current notebook and any waiting changes. The access key is excluded. Keep the backup private.</p><button class="secondary wide" data-action="export">${icon('download')}Export notebook</button><details class="help-details"><summary>Restore a backup on this device</summary><p>Restore into an empty notebook only. The connection and access key must be entered separately.</p><input class="file-picker" id="backup-file" type="file" accept="application/json,.json" aria-label="Select notebook backup"></details></div><p class="fine-print">Setbook ${VERSION} · Dates use Korea time.<br>Weights: dumbbells per dumbbell; carries per arm; barbells without the bar; machines use the stack or combined plates. Body measurements use kg and %.</p>`);
}
function manageExercises(){showModal('Your exercises',`<div class="field"><label for="manage-search">Find an exercise</label><input type="search" id="manage-search" placeholder="Search your list"></div><div id="managed-list"></div><button class="text-button" data-action="settings">Back to settings</button>`);renderManaged('');}
function renderManaged(q){const list=state.exercises.filter(e=>!e.deleted&&!e.redirectId&&normalize(e.name).includes(normalize(q))).sort((a,b)=>a.name.localeCompare(b.name));$('#managed-list').innerHTML=list.map(e=>`<button class="exercise-option" data-action="edit-exercise" data-id="${h(e.id)}"><span><strong>${h(e.name)}</strong><small>${h(BASES[e.loadBasis])}${e.archived?' · Archived':''}</small></span>${icon('edit')}</button>`).join('')||'<p class="subtle">Your exercise list will grow when you complete sets.</p>';}
function editExercise(id){const e=state.exercises.find(e=>e.id===id);if(!e)return;showModal('Exercise details',`<form id="edit-exercise-form" data-id="${h(id)}"><div class="field"><label for="ex-name">Exercise name</label><input id="ex-name" required maxlength="120" value="${h(e.name)}"></div>${exerciseFields(e)}<p class="fine-print">Renaming updates display names throughout your notebook. Logging format and weight-convention changes apply to new workout entries; existing entries keep their recorded format.</p><label class="inline-check"><input id="ex-archived" type="checkbox" ${e.archived?'checked':''}>Archive from exercise suggestions</label><p class="form-error" id="exercise-error"></p><button class="primary wide" type="submit">Save exercise</button></form><details class="help-details"><summary>Merge with another exercise</summary><p>Choose the exercise to keep. This name will become an alias, and its history will join the selected exercise.</p><div class="field"><label for="merge-target">Keep this exercise</label><select id="merge-target"><option value="">Choose…</option>${state.exercises.filter(x=>x.id!==id&&!x.deleted&&!x.redirectId).sort((a,b)=>a.name.localeCompare(b.name)).map(x=>`<option value="${h(x.id)}">${h(x.name)}</option>`).join('')}</select></div><button class="danger-button" data-action="merge-exercise" data-id="${h(id)}">Merge exercises</button></details>`);}
function entryOptions(id){const e=findEntry(id);if(!e)return;showModal('Exercise options',`<p class="modal-intro">${h(entryView(e).name)}</p><button class="secondary wide" data-action="entry-note" data-id="${h(id)}">Edit exercise note</button><button class="text-button wide" data-action="move-entry-up" data-id="${h(id)}">Move exercise up</button><button class="text-button wide" data-action="move-entry-down" data-id="${h(id)}">Move exercise down</button><button class="text-button danger-text wide" data-action="remove-entry" data-id="${h(id)}">Remove from this workout</button>`);}
function entryNote(id){const e=findEntry(id);if(!e)return;showModal('Exercise note',`<form id="entry-note-form" data-id="${h(id)}"><div class="field"><label for="entry-note">${h(entryView(e).name)}</label><textarea id="entry-note" rows="5" maxlength="2000">${h(e.notes||'')}</textarea></div><button class="primary wide">Save note</button></form>`);}
function setDetails(el){const {entry,set}=setFromElement(el);if(!set)return;showModal('Set details',`<form id="set-details-form" data-entry="${h(entry.id)}" data-id="${h(set.id)}"><p class="modal-intro">${h(entryView(entry).name)} · ${h(setDescription(set,entry))}</p><div class="field"><label for="set-kind">Set type</label><select id="set-kind">${[['work','Working set'],['warmup','Warm-up'],['drop','Drop set']].map(([k,v])=>`<option value="${k}" ${set.kind===k?'selected':''}>${v}</option>`).join('')}</select></div><label class="inline-check"><input type="checkbox" id="set-estimated" ${set.estimated?'checked':''}>Value is estimated</label><div class="button-row" style="margin-top:20px"><button class="primary">Save details</button><button class="text-button danger-text" type="button" data-action="remove-set" data-entry="${h(entry.id)}" data-id="${h(set.id)}">Delete set</button></div></form>`);}
function sessionMenu(){const s=currentSession();if(!s)return;showModal('Workout options',`<div class="field"><label for="session-label">Workout label · optional</label><input id="session-label" value="${h(s.label||'')}" maxlength="160" placeholder="Full body"></div><button class="primary wide" data-action="save-session-label">Save label</button><button class="text-button wide" data-action="close-session">Return to today</button><button class="text-button danger-text wide" data-action="delete-session" data-id="${h(s.id)}">Delete this workout</button>`);}
function finishSession(){const s=currentSession();if(!s)return;const count=completedSets(s).length;if(!count){toast('Complete at least one set before finishing your workout.');return;}const incomplete=s.entries.flatMap(e=>e.sets).filter(s=>!s.completed).length;showModal(s.status==='completed'?'Save workout':'Finish your workout',`<p class="modal-intro">${sessionSummary(s)}${incomplete?`. ${incomplete} unfinished set${incomplete===1?' is':'s are'} kept as drafts and excluded from graphs.`:'.'}</p><button class="primary wide" data-action="confirm-finish">${icon('check')}Save workout</button><button class="text-button wide" data-action="close-modal">Keep editing</button>`);}
function deleteRecord(entity,id){const collection=entity==='session'?'sessions':'measurements',r=state[collection].find(x=>x.id===id);if(!r)return;showModal(entity==='session'?'Delete workout?':'Delete reading?',`<p class="modal-intro">This removes the record from your notebook and graphs on all connected devices after syncing.</p><button class="danger-button wide" data-action="confirm-delete" data-entity="${entity}" data-id="${h(id)}">Delete record</button><button class="text-button wide" data-action="close-modal">Cancel</button>`);}
function conflictSummary(r,entity){if(!r||r.deleted)return 'Deleted record';if(entity==='session')return `${r.date||r.label||'Undated'} · ${sessionSummary(r)}${r.notes?' · '+r.notes.slice(0,160):''}`;if(entity==='measurement')return `${r.date}: ${['weightKg','bodyFatPct','skeletalMuscleKg'].filter(k=>r[k]!=null).map(k=>`${k}: ${r[k]}`).join(', ')}`;return r.name||JSON.stringify(r).slice(0,250);}
function openConflicts(){showModal('Review changes',`<p class="modal-intro">Both copies are preserved until you choose. “Use this device” replaces the last version in Sheets after your next sync.</p>${state.conflicts.map(c=>{const local=state.pending.find(o=>o.key===c.key);return `<div class="conflict-item"><strong>${h(c.entity)}</strong><p><b>In Sheets:</b> ${h(conflictSummary(c.remote,c.entity))}</p><p><b>This device:</b> ${h(conflictSummary(local?.payload,c.entity))}</p><div class="button-row"><button class="secondary" data-action="resolve-remote" data-key="${h(c.key)}">Use Sheets</button><button class="secondary" data-action="resolve-local" data-key="${h(c.key)}">Use this device</button></div><button class="text-button" data-action="conflict-json" data-key="${h(c.key)}">Inspect both full records</button></div>`;}).join('')||'<p class="subtle">No changes need review.</p>'}`);}
function downloadJSON(filename,data){const blob=new Blob([JSON.stringify(data,null,2)],{type:'application/json'}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=filename;document.body.append(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),5000);}
function exportBackup(){if(loadError){downloadJSON(`setbook-recovery-${today()}.json`,{format:'setbook-raw-recovery',exportedAt:new Date().toISOString(),raw:localStorage.getItem(STORE)});toast('Original browser data exported for recovery.');return;}downloadJSON(`setbook-backup-${today()}.json`,{format:'setbook-backup',version:1,exportedAt:new Date().toISOString(),notebook:state});toast('Backup downloaded. Keep it private.');}
async function importHistory(){
 if(!pendingImport)return;if(!configured()){toast('Connect Google Sheets before importing history.');return;}
 const btn=$('[data-action="confirm-import"]');if(btn)btn.disabled=true;
 try{const okay=await sync(true);if(!okay||state.pending.length||state.conflicts.length)throw Error('Finish syncing or reviewing waiting changes before importing.');syncing=true;updateStatus();const result=await request({action:'import',data:pendingImport});mergeSync(state,result,[]);persist();closeModal();render();toast(result.alreadyImported?'This starting history was already imported.':'Starting history imported.');if(result.warning)toast(result.warning);}
 catch(e){toast(e.message);if(btn)btn.disabled=false;}finally{syncing=false;updateStatus();}
}

document.addEventListener('click',async event=>{
 const button=event.target.closest('[data-action]');if(!button)return;if(singleTabBlocked)return;
 const a=button.dataset.action,id=button.dataset.id;
 try{
 if(a==='settings')openSettings();else if(a==='sync')await sync(true);else if(a==='start')startSession();else if(a==='add-exercise')openExercisePicker();else if(a==='new-exercise')newExercise();else if(a==='choose-exercise'){const e=state.exercises.find(e=>e.id===id);if(e)addExercise(e);}
 else if(a==='add-set'){const e=findEntry(id);if(e){if(e.sets.length>=60){toast('An exercise can contain up to 60 sets.');return;}e.sets.push(blankSet(e.sets.at(-1)));saveCurrent(true);}}
 else if(a==='copy-previous'){const e=findEntry(id),p=previousEntry(state,e.exerciseId,currentSession().id);if(p){e.sets=e.sets.filter(s=>s.completed).concat(p.entry.sets.filter(s=>s.completed).map(s=>({...clone(s),id:uid(),completed:false,failure:false,estimated:false,imported:false})));saveCurrent(true);}}
 else if(a==='entry-options')entryOptions(id);else if(a==='entry-note')entryNote(id);else if(a==='set-details')setDetails(button);
 else if(a==='remove-set'){const e=findEntry(button.dataset.entry);e.sets=e.sets.filter(s=>s.id!==id);saveCurrent();closeModal();render();}
 else if(a==='remove-entry'){const e=findEntry(id);if(e.sets.some(s=>s.completed)&&!confirm('Remove this exercise and its completed sets from this workout?'))return;const s=currentSession();s.entries=s.entries.filter(e=>e.id!==id);saveCurrent();closeModal();render();}
 else if(a==='move-entry-up'||a==='move-entry-down'){const entries=currentSession().entries,index=entries.findIndex(e=>e.id===id),target=index+(a==='move-entry-up'?-1:1);if(target>=0&&target<entries.length){[entries[index],entries[target]]=[entries[target],entries[index]];saveCurrent();}closeModal();render();}
 else if(a==='session-menu')sessionMenu();else if(a==='save-session-label'){currentSession().label=$('#session-label').value;saveCurrent();closeModal();render();}
 else if(a==='finish')finishSession();else if(a==='confirm-finish'){const s=currentSession();s.status='completed';s.finishedAt=s.finishedAt||new Date().toISOString();changed('session',s);state.activeSessionId=null;persist();closeModal();render();toast('Workout saved on this device.');}
 else if(a==='close-session'){state.activeSessionId=null;persist();closeModal();render();}
 else if(a==='edit-session'){state.activeSessionId=id;persist();location.hash='#workout';render();window.scrollTo({top:0});}
 else if(a==='repeat-session'){startSession(state.sessions.find(s=>s.id===id));}
 else if(a==='delete-session')deleteRecord('session',id);else if(a==='delete-measurement')deleteRecord('measurement',id);
 else if(a==='confirm-delete'){const entity=button.dataset.entity,k=entity==='session'?'sessions':'measurements',r=state[k].find(x=>x.id===id);r.deleted=true;changed(entity,r);if(state.activeSessionId===id)state.activeSessionId=null;persist();closeModal();render();toast('Record deleted on this device.');}
 else if(a==='measurement')openMeasurement(id);else if(a==='body-metric'){bodyMetric=button.dataset.value;renderBody();}else if(a==='goal')openGoal();
 else if(a==='theme'){document.documentElement.dataset.theme=button.dataset.value;localStorage.setItem('setbook-theme',button.dataset.value);$('meta[name="theme-color"]').content=button.dataset.value==='light'?'#f5f4ee':'#151d1c';$$('[data-action="theme"]').forEach(b=>b.setAttribute('aria-pressed',String(b===button)));}
 else if(a==='disconnect'){config={endpoint:'',key:'',remember:false};saveConfig();syncError='';openSettings();updateStatus();render();}
 else if(a==='manage-exercises')manageExercises();else if(a==='edit-exercise')editExercise(id);
 else if(a==='merge-exercise'){const source=state.exercises.find(e=>e.id===id),target=state.exercises.find(e=>e.id===$('#merge-target').value);if(!target){toast('Choose an exercise to keep.');return;}if(!confirm(`Merge “${source.name}” into “${target.name}”? Its history will be shown together.`))return;target.aliases=[...new Set([...(target.aliases||[]),source.name,...(source.aliases||[])])];changed('exercise',target);source.archived=true;source.redirectId=target.id;changed('exercise',source);manageExercises();render();}
 else if(a==='export')exportBackup();else if(a==='confirm-import')await importHistory();else if(a==='conflicts')openConflicts();
 else if(a==='resolve-remote'||a==='resolve-local'){const key=button.dataset.key,c=state.conflicts.find(c=>c.key===key),op=state.pending.find(o=>o.key===key);if(!c||!op)return;const k={session:'sessions',measurement:'measurements',exercise:'exercises',settings:'settings'}[c.entity];if(a==='resolve-remote'){state.pending=state.pending.filter(o=>o.key!==key);state[k]=state[k].filter(r=>r.id!==c.id);if(c.remote)state[k].push(c.remote);}else{op.baseRevision=c.revision;op.mutationId=uid();}state.conflicts=state.conflicts.filter(c=>c.key!==key);persist();openConflicts();render();scheduleSync();}
 else if(a==='conflict-json'){const c=state.conflicts.find(c=>c.key===button.dataset.key),op=state.pending.find(o=>o.key===c.key);showModal('Both saved versions',`<p class="fine-print">In Sheets</p><pre style="white-space:pre-wrap;overflow-wrap:anywhere;font-size:11px">${h(JSON.stringify(c.remote,null,2))}</pre><p class="fine-print">This device</p><pre style="white-space:pre-wrap;overflow-wrap:anywhere;font-size:11px">${h(JSON.stringify(op?.payload,null,2))}</pre><button class="secondary" data-action="conflicts">Back to review</button>`);}
 else if(a==='close-modal')closeModal();
 }catch(e){toast(e.message||'This action could not be completed.');}
});

document.addEventListener('input',event=>{
 const el=event.target;
 if(el.id==='exercise-search'){renderExerciseOptions(el.value);return;}if(el.id==='manage-search'){renderManaged(el.value);return;}if(el.id==='history-search'){historySearch=el.value;renderHistoryList();return;}
 if(el.id==='workout-notes'){currentSession().notes=el.value;saveCurrent();return;}
 if(el.matches('[data-field]')&&el.type!=='checkbox'){
  const {set,entry}=setFromElement(el);if(!set)return;let v=num(el.value);if(el.dataset.field==='minutes'&&v!=null)v=Math.round(v*60);const field=el.dataset.field==='minutes'?'seconds':el.dataset.field;
  set[field]=v;el.removeAttribute('aria-invalid');if(set.completed&&validateSet(set,entry.type)){set.completed=false;el.closest('.set-row').classList.remove('done');$('[data-field="completed"]',el.closest('.set-row')).checked=false;}
  saveCurrent();
 }
});
document.addEventListener('change',async event=>{
 const el=event.target;
 if(el.id==='workout-date'){currentSession().date=el.value||null;saveCurrent();return;}
 if(el.id==='progress-exercise'){selectedExercise=el.value;renderProgress();return;}if(el.id==='progress-metric'){exerciseMetric=el.value;renderProgress();return;}if(el.id==='include-estimated'){includeEstimated=el.checked;renderProgress();return;}if(el.id==='history-year'){historyYear=el.value;renderHistoryList();return;}
 if(el.matches('[data-field]')&&el.type==='checkbox'){
  const {set,entry}=setFromElement(el);if(!set)return;
  if(el.dataset.field==='completed'&&el.checked){const error=validateSet(set,entry.type);if(error){el.checked=false;toast(error);return;}registerLocal(entry);set.estimated=false;set.imported=false;}
  set[el.dataset.field]=el.checked;saveCurrent(true);return;
 }
 if(el.id==='history-file'){
  try{const file=el.files[0];if(!file)return;if(file.size>1800000)throw Error('This import file is too large.');const data=JSON.parse(await file.text());if(data.format!=='setbook-import'||data.version!==1||!Array.isArray(data.sessions)||!Array.isArray(data.exercises))throw Error('Choose the supplied history-import.json.');pendingImport=data;$('#import-preview').innerHTML=`<div class="import-preview"><strong>${data.sessions.length} workouts · ${data.exercises.length} exercise names</strong><p>Includes early sessions without exact dates. Estimates are labeled. November 11’s plan is omitted.</p><button class="primary wide" data-action="confirm-import">Import starting history</button></div>`;}catch(e){toast(e.message);}return;
 }
 if(el.id==='backup-file'){
  try{const file=el.files[0];if(!file)return;if(state.sessions.length||state.measurements.length||state.pending.length)throw Error('Restore is available only in an empty notebook. Export this notebook first, or connect the existing Sheet on your other device.');if(file.size>8000000)throw Error('This backup is too large.');const backup=JSON.parse(await file.text());if(backup.format!=='setbook-backup'||backup.version!==1||backup.notebook?.schemaVersion!==1||!Array.isArray(backup.notebook.pending)||!Array.isArray(backup.notebook.sessions)||!Array.isArray(backup.notebook.exercises)||!Array.isArray(backup.notebook.measurements)||!Array.isArray(backup.notebook.settings)||!Array.isArray(backup.notebook.conflicts))throw Error('This is not a Setbook notebook backup.');state=backup.notebook;persist();closeModal();render();toast('Notebook restored on this device. Connect the same Sheet to sync.');}catch(e){toast(e.message);}return;
 }
});
document.addEventListener('submit',async event=>{
 const form=event.target;if(!form.id)return;event.preventDefault();
 try{
 if(form.id==='connection-form'){
  const endpoint=$('#api-url').value.trim(),key=$('#api-key').value.trim();if(!/^https:\/\/script\.google\.com\/macros\/s\/[A-Za-z0-9_-]+\/exec$/.test(endpoint)){ $('#connection-error').textContent='Use the deployed https://script.google.com/macros/s/…/exec URL, without extra parameters.';return;}
  if(key.length<20){$('#connection-error').textContent='Copy the full private access key from Script properties.';return;}
  config={endpoint,key,remember:$('#remember-key').checked};saveConfig();const submit=$('button[type="submit"]',form);submit.disabled=true;$('#connection-error').textContent='';
  const okay=await sync(true);if(!form.isConnected)return;submit.disabled=false;if(okay){$('#connection-status').textContent='Connected. Your notebook is synced.';toast('Connected to Google Sheets.');render();}else $('#connection-error').textContent=syncError||'Review conflicting changes before continuing.';
 }else if(form.id==='new-exercise-form'){
  const name=$('#ex-name').value.trim().replace(/\s+/g,' ');if(!name)return;const existing=findExercise(state.exercises,name);if(existing){addExercise(existing);return;}addExercise({id:uid(),name,type:$('#ex-type').value,group:$('#ex-group').value,loadBasis:$('#ex-basis').value});
 }else if(form.id==='edit-exercise-form'){
  const e=state.exercises.find(e=>e.id===form.dataset.id),name=$('#ex-name').value.trim().replace(/\s+/g,' '),other=findExercise(state.exercises,name);if(other&&other.id!==e.id){$('#exercise-error').textContent='That name already exists. Use the merge option below.';return;}
  if(normalize(name)!==normalize(e.name))e.aliases=[...new Set([...(e.aliases||[]),e.name])];Object.assign(e,{name,type:$('#ex-type').value,group:$('#ex-group').value,loadBasis:$('#ex-basis').value,archived:$('#ex-archived').checked});changed('exercise',e);manageExercises();render();
 }else if(form.id==='measurement-form'){
  const old=state.measurements.find(m=>m.id===form.dataset.id),m={...(old||{id:form.dataset.id,_rev:0}),date:$('#m-date').value,weightKg:num($('#m-weight').value),bodyFatPct:num($('#m-fat').value),skeletalMuscleKg:num($('#m-muscle').value),notes:$('#m-notes').value};if([m.weightKg,m.bodyFatPct,m.skeletalMuscleKg].every(v=>v==null)){$('#measurement-error').textContent='Enter at least one measurement.';return;}if(old)Object.assign(old,m);else state.measurements.push(m);changed('measurement',old||m);closeModal();render();toast('Body reading saved on this device.');
 }else if(form.id==='goal-form'){
  const old=state.settings.find(s=>s.id==='preferences'),g={...(old||{id:'preferences',_rev:0}),gainKg:num($('#goal-gain').value),deadline:$('#goal-deadline').value,baselineKg:num($('#goal-baseline').value),weeklyTarget:num($('#goal-weekly').value)};if(old)Object.assign(old,g);else state.settings.push(g);changed('settings',old||g);closeModal();render();
 }else if(form.id==='entry-note-form'){findEntry(form.dataset.id).notes=$('#entry-note').value;saveCurrent();closeModal();render();}
 else if(form.id==='set-details-form'){const e=findEntry(form.dataset.entry),s=e.sets.find(s=>s.id===form.dataset.id);s.kind=$('#set-kind').value;s.estimated=$('#set-estimated').checked;saveCurrent();closeModal();render();}
 }catch(e){toast(e.message);}
});

$('#settings-button').addEventListener('click',openSettings);$('#sync-button').addEventListener('click',()=>state.conflicts.length?openConflicts():configured()?sync(true):openSettings());$('#close-modal').addEventListener('click',closeModal);
modal.addEventListener('click',event=>{if(event.target===modal){const rect=modal.getBoundingClientRect();if(event.clientX<rect.left||event.clientX>rect.right||event.clientY<rect.top||event.clientY>rect.bottom)closeModal();}});
window.addEventListener('hashchange',()=>{render();window.scrollTo({top:0});});window.addEventListener('online',()=>sync(true));window.addEventListener('offline',updateStatus);window.addEventListener('focus',()=>{if(configured()&&!modal.open)sync(true);});document.addEventListener('visibilitychange',()=>{if(document.visibilityState==='visible'&&configured())sync(true);});
window.addEventListener('beforeunload',event=>{if(!storageOK&&!loadError){event.preventDefault();event.returnValue='';}});
if(loadError)showFatal(loadError);
render();
if(configured())sync(true);
if(navigator.locks)navigator.locks.request('setbook-notebook-writer',{ifAvailable:true},async lock=>{if(!lock){singleTabBlocked=true;main.inert=true;showFatal('Setbook is already open in another tab. Close that tab, then reload here to continue safely.');return;}await new Promise(resolve=>window.addEventListener('pagehide',resolve,{once:true}));});
if('serviceWorker'in navigator){navigator.serviceWorker.register('./sw.js').then(reg=>{const offer=()=>{if(!reg.waiting)return;const banner=document.createElement('div');banner.className='update-banner';banner.innerHTML='An app update is ready. <button class="text-button">Update</button>';banner.querySelector('button').onclick=()=>{persist();reg.waiting.postMessage('ACTIVATE');banner.remove();};document.body.append(banner);};if(reg.waiting)offer();reg.addEventListener('updatefound',()=>reg.installing?.addEventListener('statechange',()=>{if(reg.waiting&&navigator.serviceWorker.controller)offer();}));}).catch(()=>{});let reloading=false;navigator.serviceWorker.addEventListener('controllerchange',()=>{if(!reloading&&navigator.serviceWorker.controller){reloading=true;if(!currentSession())location.reload();else toast('App updated. Your current session is saved. Reload when convenient.');}});}
